import{at as e,it as t,n,vt as r}from"./chunks/framework.B6nQ8gjX.js";var i=JSON.parse(`{"title":"搜尋歷程記錄","description":"","frontmatter":{},"headers":[{"level":2,"title":"1. 搜尋歷程（Search History）","slug":"_1-搜尋歷程-search-history","link":"#_1-搜尋歷程-search-history","children":[]},{"level":2,"title":"2. 關鍵字歷程（Keyword History）","slug":"_2-關鍵字歷程-keyword-history","link":"#_2-關鍵字歷程-keyword-history","children":[]},{"level":2,"title":"3. 查詢關聯（Query Associations）","slug":"_3-查詢關聯-query-associations","link":"#_3-查詢關聯-query-associations","children":[]}],"relativePath":"zh-TW/user-guide/settings/history.md","filePath":"zh-TW/user-guide/settings/history.md","lastUpdated":1795268921000}`),a={name:`zh-TW/user-guide/settings/history.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="搜尋歷程記錄" tabindex="-1">搜尋歷程記錄 <a class="header-anchor" href="#搜尋歷程記錄" aria-label="Permalink to “搜尋歷程記錄”">​</a></h1><p>三個分頁分別管理開啟記錄、搜尋關鍵字和查詢關聯。</p><h2 id="_1-搜尋歷程-search-history" tabindex="-1">1. 搜尋歷程（Search History） <a class="header-anchor" href="#_1-搜尋歷程-search-history" aria-label="Permalink to “1. 搜尋歷程（Search History）”">​</a></h2><p>記錄從搜尋結果開啟檔案、資料夾或應用程式的次數與時間。</p><ul><li><strong>排序加權</strong>：每次開啟加 1 分，上限 10 分，90 天減半。有效分達到 3 可進入 H3 級，達到 5 可進入 H5 級。快速搜尋最多分配 3 個 H5、10 個 H3 名額，內嵌搜尋為 1 個和 3 個，完整視窗不限制名額。</li><li><strong>前移範圍</strong>：歷史權重可讓項目超過同一有效符合等級、同一優先順序的其他結果。快速搜尋的類型設定會影響檔案、資料夾的完整符合等級，詳見<a href="./../search-syntax.html">搜尋語法</a>。</li><li><strong>內嵌分區</strong>：目前資料夾與全域結果分別顯示。不存在的路徑會被略過。</li><li><strong>管理操作</strong>：可按關鍵字篩選、逐項刪除、清除使用次數不超過 N 的記錄或清空全部。其他視窗新增開啟記錄後，清單會更新。關閉記錄開關後不再新增項目，現有項目仍更新次數和最近時間。</li></ul><h2 id="_2-關鍵字歷程-keyword-history" tabindex="-1">2. 關鍵字歷程（Keyword History） <a class="header-anchor" href="#_2-關鍵字歷程-keyword-history" aria-label="Permalink to “2. 關鍵字歷程（Keyword History）”">​</a></h2><p>執行結果或動作、開啟完整視窗時，記錄搜尋框中的原始查詢。只輸入文字後關閉快速搜尋，不會新增記錄。</p><ul><li>按 <strong>Alt+Up / Alt+Down</strong> 翻閱最近搜尋詞，按 <strong>Ctrl+Delete</strong> 刪除目前詞條。</li><li>可篩選、逐項刪除、清空全部，或按使用次數清理。本頁有獨立的記錄開關；關閉後不再新增詞條，現有詞條仍累加次數。</li></ul><h2 id="_3-查詢關聯-query-associations" tabindex="-1">3. 查詢關聯（Query Associations） <a class="header-anchor" href="#_3-查詢關聯-query-associations" aria-label="Permalink to “3. 查詢關聯（Query Associations）”">​</a></h2><p>獨立儲存<strong>查詢詞 → 目標路徑</strong>關聯。</p><ul><li>同一正規化查詢下，從一般搜尋結果開啟目標至少 <strong>3 次</strong>後，關聯才可用於補充結果。只靠關聯找出的項目再次被開啟，不會增加確認次數。</li><li>每次查詢最多補充 <strong>1 項</strong>關聯，不補充低優先順序目標。只靠關聯找出的結果排在直接符合之後。</li><li>可篩選、逐項刪除或清空關聯，路徑使用分數會保留。</li></ul>`,11)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};